    `seo`, `seo_title`, `seo_desc`, `seo_keyword`, `updated_at`, `created_at`
  ) VALUES (
    'comic-manh-ho-jang-san', 'Mãnh Hổ Jang San', 'manh-ho-jang-san', '[\"THE JANGSAN TIGER; 장산범\"]', 'https://tachserver.site/cdn3/uploads/minh_hoa/manh-ho-jang-san-1785413327.jpg', 'https://tachserver.site/cdn3/uploads/minh_hoa/manh-ho-jang-san-1785413327.jpg',
    '[\"Leesin Team\"]', 'Đang tiến hành', '[\"Tình Yêu\",\"Manhwa\",\"Đam Mỹ\",\"Hài Hước\",\"Kinh Dị\",\"Supernatural\",\"Boy Love\",\"Drama\",\"Fantasy\",\"Horror\",\"Psychological\",\"18+\"]', '“Bạn cùng phòng” vừa mới về nhà dạo này cứ lạ lạ sao ấy. Nhà mình mà cũng bày đặt nhấn chuông, rồi hết lần này đến lần khác cứ gặng hỏi xem tôi thích cái gì… “Nhưng chuyện đó quan trọng gì chứ? Dù sao đi nữa, anh vẫn là người thích em nhất mà.” “Không hề nhé… Em mới là người bị anh ghét nhất thì có… Chính miệng anh bảo ghét em cơ mà, cái đó thì không nhầm được đâu. Lần này anh thề, anh sẽ tống cổ em ra khỏi nhà. Anh nói thật đấy.” “Gunpil, đồ khốn kiếp, em thật sự là kẻ tệ hại nhất trên đời luôn!!” Ái chà… anh ấy cáu thật rồi… Chẳng phải hôm qua vừa mới làm hòa sao. “Em sẽ làm cái gì đó mà anh thực sự thích nhá”. ‘Anh Yeonseung’ vốn thích mấy thứ ‘đâm sâu’ vào mà đúng không? Để em giúp anh nới lỏng phía sau nhé— …Nhưng mà anh ơi, mắt anh lúc nào cũng đỏ ngầu thế này sao?”', 'team-lessin-comic', 'Lessin Comic',
    7730, 308, 1542, 7709,
    308, 1542, 7709,
    925, 5, 4.9, 64,
    0, 0, 0,
    '{\"focusKeyword\":\"Mãnh Hổ Jang San\",\"metaTitle\":\"Mãnh Hổ Jang San | Leesin Comic\",\"metaDesc\":\"“Bạn cùng phòng” vừa mới về nhà dạo này cứ lạ lạ sao ấy. Nhà mình mà cũng bày đặt nhấn chuông, rồi hết lần này đến lần khác cứ gặng hỏi xem tôi thích \",\"canonicalUrl\":\"https://leesincomic.com/truyen-tranh/manh-ho-jang-san.html\",\"score\":92,\"schemaType\":\"ComicBook\",\"ogImage\":\"https://tachserver.site/cdn3/uploads/minh_hoa/manh-ho-jang-san-1785413327.jpg\"}', 'Mãnh Hổ Jang San | Leesin Comic', '“Bạn cùng phòng” vừa mới về nhà dạo này cứ lạ lạ sao ấy. Nhà mình mà cũng bày đặt nhấn chuông, rồi hết lần này đến lần khác cứ gặng hỏi xem tôi thích ', 'Mãnh Hổ Jang San', '2026-09-10T05:00:00.000Z', '2026-09-10T05:00:00.000Z'
