  ) VALUES (
    'comic-nguoi-dan-ong-cua-than', 'Người Đàn Ông Của Thần', 'nguoi-dan-ong-cua-than', '[\"[성비단 인외탐미] 신의 남자\"]', 'https://tachserver.site/cdn3/uploads/minh_hoa/nguoi-dan-ong-cua-than--1787500143.jpg', 'https://tachserver.site/cdn3/uploads/minh_hoa/nguoi-dan-ong-cua-than--1787500143.jpg',
    '[\"Leesin Team\"]', 'Đang tiến hành', '[\"Truyện Màu\",\"Kịch Tính\",\"Tình Cảm\",\"BoyLove\",\"Yaoi\",\"Đã Full\",\"Manhwa\",\"Viễn Tưởng\",\"Supernatural\",\"Boy Love\",\"Drama\",\"Fantasy\",\"18+\",\"Oneshot\"]', 'Nơi tu viện vắng lặng của ngôi làng — chốn đã hoàn toàn cô lập với thế giới bên ngoài bởi mặc cảm tội lỗi cùng sự tuyệt vọng tột cùng — linh mục Bence đang định bóp cò khẩu súng trường kết liễu đời mình. Đúng lúc ấy, một luồng bạch quang rực rỡ đột ngột xé toạc không gian, khiến gã giật mình sững lại. Kể từ khoảnh khắc đó, Bence bắt đầu tin rằng thứ đang treo lơ lửng trên trần nhà kho gác mái chính là Hiện Thân của Chúa. Giao phó cả thể xác lẫn linh hồn cho \'Vị Thần\' quái dị sở hữu chiếc lưỡi rùa như rắn cùng những xúc tu phát sáng kia, gã dần chìm sâu vào sự sùng bái mù quáng và bị thứ đó thao túng, nuốt chửng hoàn toàn tâm trí.', 'team-lessin-comic', 'Lessin Comic',
    1007, 62, 220, 958,
    62, 220, 958,
    114, 0, 4.9, 15,
    0, 0, 0,
    '{\"focusKeyword\":\"Người Đàn Ông Của Thần\",\"metaTitle\":\"Người Đàn Ông Của Thần | Leesin Comic\",\"metaDesc\":\"Nơi tu viện vắng lặng của ngôi làng — chốn đã hoàn toàn cô lập với thế giới bên ngoài bởi mặc cảm tội lỗi cùng sự tuyệt vọng tột cùng — linh mục Bence\",\"canonicalUrl\":\"https://leesincomic.com/truyen-tranh/nguoi-dan-ong-cua-than-.html\",\"score\":92,\"schemaType\":\"ComicBook\",\"ogImage\":\"https://tachserver.site/cdn3/uploads/minh_hoa/nguoi-dan-ong-cua-than--1787500143.jpg\"}', 'Người Đàn Ông Của Thần | Leesin Comic', 'Nơi tu viện vắng lặng của ngôi làng — chốn đã hoàn toàn cô lập với thế giới bên ngoài bởi mặc cảm tội lỗi cùng sự tuyệt vọng tột cùng — linh mục Bence', 'Người Đàn Ông Của Thần', '2026-09-10T05:00:00.000Z', '2026-09-10T05:00:00.000Z'
