  ) VALUES (
    'comic-chung-giuong-voi-nam-chinh', 'Chung Giường Với Nam Chính', 'chung-giuong-voi-nam-chinh', '[\"남주와 침대에서 뒹굴었다\"]', 'https://tachserver.site/cdn3/uploads/minh_hoa/chung-giuong-voi-nam-chinh-1788332276.jpg', 'https://tachserver.site/cdn3/uploads/minh_hoa/chung-giuong-voi-nam-chinh-1788332276.jpg',
    '[\"Leesin Team\"]', 'Đang tiến hành', '[\"Lãng Mạn\",\"Manhwa\",\"Drama\"]', 'Bị mắc kẹt trong một vòng lặp thời gian không hồi kết, một quý tộc nhận ra rằng mình chẳng qua chỉ là “nam phụ” trong một câu chuyện đã được định sẵn. Dù thay đổi điều gì, người phụ nữ mà anh yêu vẫn luôn lựa chọn cùng một người đàn ông và cuối cùng phải nhận một kết cục bi thảm. Sau vô số lần thử nghiệm thất bại, kể cả việc sát hại, anh quyết định thực hiện một kế hoạch điên rồ: chinh phục nam chính. Khi những hành động táo bạo của anh ngày càng vượt qua giới hạn, ranh giới giữa sự thao túng, ám ảnh và cảm xúc chân thật cũng dần trở nên mơ hồ, mở ra một câu chuyện tình cảm giả tưởng đầy kịch tính.', 'team-yoru-translation-team-out', 'Yoru Translation Team (out)',
    43, 15, 75, 42,
    15, 75, 42,
    50, 0, 4.9, 15,
    0, 0, 0,
    '{\"focusKeyword\":\"Chung Giường Với Nam Chính\",\"metaTitle\":\"Chung Giường Với Nam Chính | Leesin Comic\",\"metaDesc\":\"Bị mắc kẹt trong một vòng lặp thời gian không hồi kết, một quý tộc nhận ra rằng mình chẳng qua chỉ là “nam phụ” trong một câu chuyện đã được định sẵn.\",\"canonicalUrl\":\"https://leesincomic.com/truyen-tranh/chung-giuong-voi-nam-chinh.html\",\"score\":92,\"schemaType\":\"ComicBook\",\"ogImage\":\"https://tachserver.site/cdn3/uploads/minh_hoa/chung-giuong-voi-nam-chinh-1788332276.jpg\"}', 'Chung Giường Với Nam Chính | Leesin Comic', 'Bị mắc kẹt trong một vòng lặp thời gian không hồi kết, một quý tộc nhận ra rằng mình chẳng qua chỉ là “nam phụ” trong một câu chuyện đã được định sẵn.', 'Chung Giường Với Nam Chính', '2026-09-02T05:00:00.000Z', '2026-09-02T05:00:00.000Z'
