    `seo`, `seo_title`, `seo_desc`, `seo_keyword`, `updated_at`, `created_at`
  ) VALUES (
    'comic-ho-ly-bat-tu', 'Hồ Ly Bất Tử', 'ho-ly-bat-tu', '[\"불사의 꼬리\"]', 'https://tachserver.site/cdn3/uploads/minh_hoa/ho-ly-bat-tu-1778596345.jpg', 'https://tachserver.site/cdn3/uploads/minh_hoa/ho-ly-bat-tu-1778596345.jpg',
    '[\"Leesin Team\"]', 'Đang tiến hành', '[\"Truyện Màu\",\"Kịch Tính\",\"Tình Cảm\",\"BoyLove\",\"Manhwa\",\"Đam Mỹ\",\"Hài Hước\",\"Supernatural\",\"Boy Love\",\"Drama\",\"Horror\",\"18+\"]', '\"Muốn hoá giải được lời nguyền này, chỉ còn một cách: Để mặc cho yêu quái nuốt chửng nó.\" Tìm đến một ngôi đền hẻo lánh với hy vọng thoát khỏi lời nguyền quái ác đang đeo bám, Haegang không ngờ mình lại rơi vào \"miệng cọp\" khi chạm trán Yeonho — một gã hồ ly đầy nguy hiểm. Thứ mà Yeonho muốn không phải mạng sống của anh, mà là linh hồn đang ẩn mình bên trong đó. Để đạt được mục đích tu luyện thành Cửu Vĩ Hồ, Yeonho đưa ra một giao kèo đầy cám dỗ: Hắn sẽ bảo vệ Haegang trước lời nguyền của mãng xà, nhưng đổi lại, Haegang phải trả giá bằng chính sinh khí của mình. Giữa vòng vây của định mệnh, gã hồ ly khẽ nở nụ cười đầy ẩn ý: \"Được rồi, đến giờ \'thưởng thức\' bữa tối rồi.\"', 'team-lessin-comic', 'Lessin Comic',
    4695, 211, 1172, 4690,
    211, 1172, 4690,
    562, 4, 4.9, 39,
    0, 0, 0,
    '{\"focusKeyword\":\"Hồ Ly Bất Tử\",\"metaTitle\":\"Hồ Ly Bất Tử | Leesin Comic\",\"metaDesc\":\"\\\"Muốn hoá giải được lời nguyền này, chỉ còn một cách: Để mặc cho yêu quái nuốt chửng nó.\\\" Tìm đến một ngôi đền hẻo lánh với hy vọng thoát khỏi lời ngu\",\"canonicalUrl\":\"https://leesincomic.com/truyen-tranh/ho-ly-bat-tu.html\",\"score\":92,\"schemaType\":\"ComicBook\",\"ogImage\":\"https://tachserver.site/cdn3/uploads/minh_hoa/ho-ly-bat-tu-1778596345.jpg\"}', 'Hồ Ly Bất Tử | Leesin Comic', '\"Muốn hoá giải được lời nguyền này, chỉ còn một cách: Để mặc cho yêu quái nuốt chửng nó.\" Tìm đến một ngôi đền hẻo lánh với hy vọng thoát khỏi lời ngu', 'Hồ Ly Bất Tử', '2026-08-17T05:00:00.000Z', '2026-08-17T05:00:00.000Z'
