  ) VALUES (
    'comic-nhat-ky-idol-cua-toi', 'Nhật Ký Idol Của Tôi', 'nhat-ky-idol-cua-toi', '[]', 'https://tachserver.site/cdn3/uploads/minh_hoa/nhat-ky-idol-cua-toi-1776184754.jpg', 'https://tachserver.site/cdn3/uploads/minh_hoa/nhat-ky-idol-cua-toi-1776184754.jpg',
    '[\"Leesin Team\"]', 'Đang tiến hành', '[\"Tình Yêu\",\"Manhwa\",\"Boy Love\",\"Drama\",\"Fantasy\",\"Psychological\",\"18+\"]', 'Chàng thần tượng Singapore vừa bí ẩn, liều lĩnh, vừa gai góc, thẳng thắn. Cậu đang đứng trên đỉnh cao khi là thần tượng được săn đón nhất tại Hàn Quốc. Cậu đã phải trải qua một năm đầy sóng gió! Khi đang ở trên đỉnh cao, cậu chấp nhận lời mời của nhân viên và uống nước trong phòng chờ của buổi hòa nhạc. Ngay sau đó, cậu đã chìm vào giấc ngủ và bị một người đàn ông to lớn tấn công. Seong Euigeon (người đàn ông to lớn đó) đã lợi dụng tình huống này để ép Kang Beom làm mọi việc mà hắn có thể tưởng tượng ra!', 'team-lessin-comic', 'Lessin Comic',
    11799, 531, 2832, 11799,
    531, 2832, 11799,
    1415, 4, 4.9, 98,
    0, 1, 0,
    '{\"focusKeyword\":\"Nhật Ký Idol Của Tôi\",\"metaTitle\":\"Nhật Ký Idol Của Tôi | Leesin Comic\",\"metaDesc\":\"Chàng thần tượng Singapore vừa bí ẩn, liều lĩnh, vừa gai góc, thẳng thắn. Cậu đang đứng trên đỉnh cao khi là thần tượng được săn đón nhất tại Hàn Quốc\",\"canonicalUrl\":\"https://leesincomic.com/truyen-tranh/nhat-ky-idol-cua-toi.html\",\"score\":92,\"schemaType\":\"ComicBook\",\"ogImage\":\"https://tachserver.site/cdn3/uploads/minh_hoa/nhat-ky-idol-cua-toi-1776184754.jpg\"}', 'Nhật Ký Idol Của Tôi | Leesin Comic', 'Chàng thần tượng Singapore vừa bí ẩn, liều lĩnh, vừa gai góc, thẳng thắn. Cậu đang đứng trên đỉnh cao khi là thần tượng được săn đón nhất tại Hàn Quốc', 'Nhật Ký Idol Của Tôi', '2026-05-15T05:00:00.000Z', '2026-05-15T05:00:00.000Z'
